INSERT INTO public.biblioteca_vectores (id,coleccion,materia,contenido,num_articulo,fuente,metadata,embedding,jurisdiccion,fuente_tipo,es_norma_vigente,revision_pendiente,instrumento_id,num_articulo_norm,hash_contenido,ingest_batch,ingested_at) VALUES
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:349','mayalex_normativos','00_CONSTITUCIONAL','La expropiación de bienes con fines de reforma agraria o de ensanche y mejoramiento de poblaciones o cualquier otro propósito de interés nacional que determine la Ley, se hará mediante indemnización justipreciada por pagos al contado y en su caso, bonos de la deuda agraria. Dichos bonos serán de aceptación obligatoria, gozarán de garantías suficientes por parte del Estado y tendrán los valores nominales, plazos de redención, tasas de interés y demás requisitos que la Ley de Reforma Agraria determine.','349','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":351,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"8387264b77d694120ec8ef92213316c3b688cc4349bc370b528a4e70f9a35aa8","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a349","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','349','8387264b77d694120ec8ef92213316c3b688cc4349bc370b528a4e70f9a35aa8','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:350','mayalex_normativos','00_CONSTITUCIONAL','Los bienes expropiables para fines de Reforma Agraria o de ensanche y mejoramiento de poblaciones, son exclusivamente los predios rústicos y sus mejoras útiles y necesarias que se encuentren adheridas a los mismos y cuya separación pudiere menoscabar la unidad económica productiva.','350','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":352,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"c970f70eeffd42ad5ffc49f267ddb1ab9dec88ca0d636636d27318ed9721a2dc","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a350","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','350','c970f70eeffd42ad5ffc49f267ddb1ab9dec88ca0d636636d27318ed9721a2dc','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:351','mayalex_normativos','00_CONSTITUCIONAL','El sistema tributario se regirá por los principios de legalidad, proporcionalidad, generalidad y equidad de acuerdo con la capacidad económica del contribuyente.','351','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":353,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"f4038c329c06cb0e0b6a5ba410f2224f0ad3fb1f962cfc27adfb8c1d41660531","ubicacion":["CAPITULO IV","DEL RÉGIMEN FINANCIERO"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a351","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','351','f4038c329c06cb0e0b6a5ba410f2224f0ad3fb1f962cfc27adfb8c1d41660531','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:352','mayalex_normativos','00_CONSTITUCIONAL','Forman la Hacienda Pública:

1. Todos los bienes muebles e inmuebles del Estado;
2. Todos sus créditos activos; y,
3. Sus disponibilidades líquidas.','352','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":354,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"c738941306714ec174506927280d61c744e55b823ca2f75d7b09f48fdb644569","ubicacion":["CAPITULO IV","DE LA HACIENDA PÚBLICA"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a352","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','352','c738941306714ec174506927280d61c744e55b823ca2f75d7b09f48fdb644569','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:353','mayalex_normativos','00_CONSTITUCIONAL','Son obligaciones financieras del Estado:
1. Las deudas legalmente contraídas para gastos corrientes o de inversión, originadas en la ejecución del Presupuesto General de Ingresos y Egresos; y,
2. Las demás deudas legalmente reconocidas por el Estado.','353','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":355,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"cb4a6d9477d8e37272db8b756984c86508e8fde34f059e1a717e5937ec907de8","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a353","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','353','cb4a6d9477d8e37272db8b756984c86508e8fde34f059e1a717e5937ec907de8','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:354','mayalex_normativos','00_CONSTITUCIONAL','Los bienes fiscales o patrimoniales solamente podrán ser adjudicados o enajenados a las personas y en la forma y condiciones que determinen las leyes.

El Estado se reserva la potestad de establecer o modificar la demarcación de las zonas de control y protección de los recursos naturales en el territorio nacional.','354','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":356,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"c18d3e917fb4ce78b438d3f5e092b5c377358816115635ad6e35964587f005e9","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a354","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','354','c18d3e917fb4ce78b438d3f5e092b5c377358816115635ad6e35964587f005e9','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:355','mayalex_normativos','00_CONSTITUCIONAL','La administración de los fondos públicos corresponde al Poder Ejecutivo.

Para la percepción custodia y erogación de dichos fondos, habrá un servicio general de tesorería.

El Poder Ejecutivo, sin embargo, podrá delegar en el Banco Central, las funciones de recaudador y depositario.

También la ley podrá establecer servicios de pagadurías especiales.','355','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":357,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"4c7b3109d2e9858fc85b6146a0e54a70276b483ddc21906a2371be41d7f2392d","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a355","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','355','4c7b3109d2e9858fc85b6146a0e54a70276b483ddc21906a2371be41d7f2392d','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:356','mayalex_normativos','00_CONSTITUCIONAL','El Estado solamente garantiza el pago de la deuda pública, que contraigan los gobiernos constitucionales, de acuerdo con esta Constitución y las leyes.

Cualquier norma o acto que contravenga lo dispuesto en este artículo, hará incurrir a los infractores en responsabilidad civil, penal y administrativa, que será imprescriptible.','356','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":358,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"9e6dcb2cc112fbe1fca90862e9dd0ef47fa35b0b477bb5a4898635c924235779","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a356","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','356','9e6dcb2cc112fbe1fca90862e9dd0ef47fa35b0b477bb5a4898635c924235779','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:357','mayalex_normativos','00_CONSTITUCIONAL','Las autorizaciones de endeudamiento externo e interno del gobierno central, organismos descentralizados y gobiernos municipales, que incluyan garantías y avales del Estado, serán reguladas por la ley.','357','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":359,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"f1acd9f765c8d0a0224a34d3870c1d42559657cc52342586a407b888a2480aa7","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a357","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','357','f1acd9f765c8d0a0224a34d3870c1d42559657cc52342586a407b888a2480aa7','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:358','mayalex_normativos','00_CONSTITUCIONAL','Los gobiernos locales podrán realizar operaciones de crédito interno bajo su exclusiva responsabilidad, pero requerirán las autorizaciones señaladas por leyes especiales.','358','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":360,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"ebac76b3b67a63857df37e5b1b2420c02e77780354926ebc1f69d70dc9205c8f","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a358","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','358','ebac76b3b67a63857df37e5b1b2420c02e77780354926ebc1f69d70dc9205c8f','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:359','mayalex_normativos','00_CONSTITUCIONAL','La tributación, el gasto y el endeudamiento públicos, deben guardar proporción con el producto interno bruto, de acuerdo con la ley.','359','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":361,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"5c525629c0e140f2480e5e19a9b874328f34522b1380c80542823597e741e1e4","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a359","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','359','5c525629c0e140f2480e5e19a9b874328f34522b1380c80542823597e741e1e4','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:360','mayalex_normativos','00_CONSTITUCIONAL','Los contratos que el Estado celebre para la ejecución de obras públicas, adquisición de suministros y servicios, de compra-venta o arrendamiento de bienes, deberán ejecutarse previa licitación, concurso o subasta, de conformidad con la ley.

Se exceptúan los contratos que tengan por objeto proveer a las necesidades ocasionadas por un estado de emergencia y los que por su naturaleza no puedan celebrarse, sino con persona determinada.','360','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":362,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"4e302360179e248ed1672ec3ea9397732f0ed57bc96531e62f49e6155e20403d","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a360","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','360','4e302360179e248ed1672ec3ea9397732f0ed57bc96531e62f49e6155e20403d','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:361','mayalex_normativos','00_CONSTITUCIONAL','Son recursos financieros del Estado:

1. Los ingresos que perciba por impuestos, tasas, contribuciones, regalías, donaciones o por cualquier otro concepto;

2. Los ingresos provenientes de empresas estatales, de capital mixto o de aquellas en que el Estado tenga participación social; y,

3. Los ingresos extraordinarios que provengan del crédito público o de cualquier otra fuente.','361','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":363,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"68109045c2e056f60d109ef22bf193ff9a648250d39f41244e833adb954dc53b","ubicacion":["CAPITULO VI","DEL","PRESUPUESTO"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a361","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','361','68109045c2e056f60d109ef22bf193ff9a648250d39f41244e833adb954dc53b','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:362','mayalex_normativos','00_CONSTITUCIONAL','Todos los ingresos y egresos fiscales constarán en el Presupuesto General de la República, que se votará anualmente de acuerdo con la política económica planificada y con los planes anuales operativos aprobados por el Gobierno.','362','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":364,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"a81db93f42a6c9761529f8536c29f98c2a94a37b38e67cb372557f5bdbe4c966","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a362","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','362','a81db93f42a6c9761529f8536c29f98c2a94a37b38e67cb372557f5bdbe4c966','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:363','mayalex_normativos','00_CONSTITUCIONAL','Todos los ingresos fiscales ordinarios constituirán un sólo fondo.

No podrá crearse ingreso alguno destinado a un fin específico. No obstante, la ley podrá afectar ingresos al servicio de la deuda pública y disponer que el producto de determinados impuestos y contribuciones generales, sea dividido entre la Hacienda Nacional y la de los municipios, en proporciones o cantidades previamente señaladas.

La Ley podrá, asimismo, de conformidad con la política planificada, autorizar a determinadas empresas estatales o mixtas para que perciban, administren o inviertan recursos financieros provenientes del ejercicio de actividades económicas que les correspondan.','363','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":365,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"69b54a361547d63ad028560266861e95c196190c25bcb196b85a2ea4ae74c95d","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a363","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','363','69b54a361547d63ad028560266861e95c196190c25bcb196b85a2ea4ae74c95d','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:364','mayalex_normativos','00_CONSTITUCIONAL','No podrá hacerse ningún compromiso o efectuarse pago alguno fuera de las asignaciones votadas en el Presupuesto, o en contravención a las normas presupuestarias.

Los infractores serán responsables civil, penal y administrativamente.','364','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":366,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"e131a16239b55cc866282be8434c4344c69552814bd49f2e72fd3f4f2cfe9b74","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a364","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','364','e131a16239b55cc866282be8434c4344c69552814bd49f2e72fd3f4f2cfe9b74','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:365','mayalex_normativos','00_CONSTITUCIONAL','El Poder Ejecutivo, bajo su responsabilidad y siempre que el Congreso Nacional no estuviere reunido, podrá contratar empréstitos, variar el destino de una partida autorizada o abrir créditos adicionales, para satisfacer necesidades urgentes o imprevistos en caso de guerra, conmoción interna o calamidad pública, o para atender compromisos internacionales, de todo lo cual dará cuenta pormenorizada al Congreso Nacional en la subsiguiente legislatura.

En la misma forma procederá cuando se trate de obligaciones a cargo del Estado provenientes de sentencia definitivas firmes, para el pago de prestaciones laborales, cuando no existiere partida o ésta estuviere agotada.','365','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":367,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"761fa80748d3a29e6a9303a7f5ebfaf4f653dbff259bf44f4bdf26573fda1280","ubicacion":[],"constancias":[{"nota":117,"tipo":"INTERPRETACION_AUTENTICA","texto":"Artículo 365. Interpretado por Decreto No.169-86 del 30 de octubre de 1986. Publicado en el Diario Oficial La Gaceta No. 25,097 del 10 de diciembre de 1986.","decretos":["169-86"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a365","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (interpretación auténtica anotada): edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','365','761fa80748d3a29e6a9303a7f5ebfaf4f653dbff259bf44f4bdf26573fda1280','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:366','mayalex_normativos','00_CONSTITUCIONAL','El Presupuesto será votado por el Poder Legislativo con vista al Proyecto que presente el Poder Ejecutivo.','366','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":368,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"9affebbbc2370efa3cea8052938683ca46f08815536ccd15d5a47029b793d16e","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a366","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','366','9affebbbc2370efa3cea8052938683ca46f08815536ccd15d5a47029b793d16e','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:367','mayalex_normativos','00_CONSTITUCIONAL','El proyecto de Presupuesto será presentado por el Poder

Ejecutivo al Congreso Nacional, dentro de los primeros quince (15) días del mes de septiembre de cada año.','367','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":369,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"58e7bde504b57ad6b3dde315787367c5ae0bcf2a0b6a8b04e3ef9ef40097b200","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a367","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','367','58e7bde504b57ad6b3dde315787367c5ae0bcf2a0b6a8b04e3ef9ef40097b200','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:368','mayalex_normativos','00_CONSTITUCIONAL','La Ley Orgánica del Presupuesto establecerá lo concerniente a la preparación, elaboración, ejecución y liquidación del presupuesto. Cuando al cierre de un ejercicio fiscal no se hubiere votado el Presupuesto para el nuevo ejercicio, continuará en vigencia el correspondiente al período anterior.','368','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":370,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"ac35c515320cd5b4b1c4f9d8f89f832372d20c89655ecd47ccce1f5838e26691","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a368","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','368','ac35c515320cd5b4b1c4f9d8f89f832372d20c89655ecd47ccce1f5838e26691','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:369','mayalex_normativos','00_CONSTITUCIONAL','La Ley determinará la organización y funcionamiento de la Proveeduría General de la República.','369','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":371,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"ea80d26228412e72fe1607720eeb4926a60b75bfed56db720f1414a8af194f1a","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a369","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','369','ea80d26228412e72fe1607720eeb4926a60b75bfed56db720f1414a8af194f1a','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:370','mayalex_normativos','00_CONSTITUCIONAL','Derogado','370','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":372,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"82ae0c99685fbe507ce253c745b8e6d7b7ae6bbbcd5f3eba6efccfda805740e7","ubicacion":[],"constancias":[{"nota":118,"tipo":"DEROGACION_TOTAL","texto":"Artículo 370. Derogado por Decreto No.268-2002 del 17 de enero del 2002 y publicado en el Diario Oficial La Gaceta No. 29,691 de fecha 25 de enero del 2002.Ratificado por Decreto No.2-2002 del 25 de enero del 2002 y publicado en el Diario Oficial La Gaceta Nº29,800 de fecha 6 de junio del 2002.","decretos":["268-2002","2-2002"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a370","derogado_por":"D.268-2002","clasificacion_propuesta":{"vigencia":"DEROGADO","rol":"CONTEXT","motivo":"DEROGADO por D.268-2002 según la edición CEDIJ; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','370','82ae0c99685fbe507ce253c745b8e6d7b7ae6bbbcd5f3eba6efccfda805740e7','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:371','mayalex_normativos','00_CONSTITUCIONAL','La fiscalización preventiva de la ejecución del Presupuesto General de Ingresos y Egresos de la República, estará a cargo del Poder Ejecutivo, que deberá especialmente:

1. Verificar la recaudación y vigilar la custodia, el compromiso y la erogación de fondos públicos; y,

2. Aprobar todo egreso de fondos públicos, de acuerdo con el presupuesto.

La Ley establecerá los procedimientos y alcances de esta fiscalización.','371','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":373,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"08973b146d18ed742a9f7b25d1eeb879d30cdb616ee5fc080be419a658683cc5","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a371","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','371','08973b146d18ed742a9f7b25d1eeb879d30cdb616ee5fc080be419a658683cc5','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:372','mayalex_normativos','00_CONSTITUCIONAL','La fiscalización preventiva de las instituciones descentralizadas y de las municipalidades, se verificará de acuerdo con lo que determinan las leyes respectivas.','372','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":374,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"fd3042aee7e497bb5385d3e557530c65ea6e3cd9b9f21035408f667c84137101","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a372","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','372','fd3042aee7e497bb5385d3e557530c65ea6e3cd9b9f21035408f667c84137101','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:373','mayalex_normativos','00_CONSTITUCIONAL','La reforma de esta Constitución podrá decretarse por el Congreso Nacional, en sesiones ordinarias, con dos tercios (2/3) de votos de la totalidad de sus miembros. El decreto señalará al efecto el artículo o artículos que hayan de reformarse, debiendo ratificarse por la subsiguiente legislatura ordinaria, por igual número de votos, para que entre en vigencia.','373','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":375,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"ecc759a01050777484ca8213607e9369b1e833039a1a14a82e0e82bee2fcca86","ubicacion":["TITULO VII","DE LA REFORMA Y LA INVIOLABILIDAD DE LA CONSTITUCIÓN","CAPITULO I","DE LA REFORMA DE LA CONSTITUCIÓN"],"constancias":[{"nota":119,"tipo":"INTERPRETACION_AUTENTICA","texto":"Artículo 373. Interpretado por Decreto No. 169-86 del 30 de octubre de 1986, publicado en el Diario Oficial la Gaceta No. 25,097 del 10 de diciembre de 1986.","decretos":["169-86"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a373","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (interpretación auténtica anotada): edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','373','ecc759a01050777484ca8213607e9369b1e833039a1a14a82e0e82bee2fcca86','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:374','mayalex_normativos','00_CONSTITUCIONAL','No podrán reformarse, en ningún caso, el artículo anterior, el presente artículo, los artículos constitucionales que se refieren a la forma de gobierno, al territorio nacional, al período presidencial, a la prohibición para ser nuevamente Presidente de la República, el ciudadano que lo haya desempeñado bajo cualquier título y el referente a quienes no pueden ser Presidentes de la República por el período subsiguiente.','374','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":376,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"9334e6ab8f0d664f83b744bd8f314a0208aa9d70684f832c731c728c26afe468","ubicacion":[],"constancias":[{"nota":120,"tipo":"INTERPRETACION_AUTENTICA","texto":"Artículo 373. Interpretado por Decreto No. 169-86 del 30 de octubre de 1986, publicado en el Diario Oficial la Gaceta No. 25,097 del 10 de diciembre de 1986.","decretos":["169-86"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a374","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible (interpretación auténtica anotada): edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','374','9334e6ab8f0d664f83b744bd8f314a0208aa9d70684f832c731c728c26afe468','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:375','mayalex_normativos','00_CONSTITUCIONAL','Esta Constitución no pierde su vigencia ni deja de cumplirse por acto de fuerza o cuando fuere supuestamente derogada o modificada por cualquier otro medio y procedimiento distintos del que ella mismo dispone. En estos casos, todo ciudadano investido o no de autoridad, tiene el deber de colaborar en el mantenimiento o restablecimiento de su afectiva vigencia.

Serán juzgados, según esta misma constitución y las leyes expedidas en conformidad con ella, los responsables de los hechos señalados en la primera parte del párrafo anterior, lo mismo que los principales funcionarios de los gobiernos que se organicen subsecuentemente, si no han contribuido a restablecer inmediatamente el imperio de esta Constitución y a las autoridades constituidas conforme a ella.

El Congreso puede decretar con el voto de la mayoría absoluta de sus miembros, la incautación de todo o parte de los bienes de esas mismas personas y de quienes se hayan enriquecido al amparo de la suplantación de la soberanía popular o de la usurpación de los poderes públicos, para resarcir a la República de los perjuicios que se le hayan causado.','375','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":377,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"8f79044df2eaf2f1448d3d51f01008cff5304bdbca8ac1f57143123185ff1b43","ubicacion":["CAPITULO II","DE LA INVIOLABILIDAD DE LA CONSTITUCIÓN"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a375","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','375','8f79044df2eaf2f1448d3d51f01008cff5304bdbca8ac1f57143123185ff1b43','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:376','mayalex_normativos','00_CONSTITUCIONAL','Todas las leyes, decretos-leyes, decretos, reglamentos, órdenes y demás disposiciones que estuvieren en vigor al promulgarse este Constitución, continuarán observándose en cuanto no se opongan a ella, o mientras no fueren legalmente derogados o modificados.','376','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":378,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"0fb46851209ba0c7df37bad8dda442ac8e8547e4237362bbbe85138fce8a5e5f","ubicacion":["TITULO VIII","DE LAS DISPOSICIONES TRANSITORIAS","Y DE LA VIGENCIA DE LA CONSTITUCION","CAPITULO I","DE LAS DISPOSICIONES TRANSITORIAS"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a376","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','376','0fb46851209ba0c7df37bad8dda442ac8e8547e4237362bbbe85138fce8a5e5f','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:377','mayalex_normativos','00_CONSTITUCIONAL','Derogado','377','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":379,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"82ae0c99685fbe507ce253c745b8e6d7b7ae6bbbcd5f3eba6efccfda805740e7","ubicacion":[],"constancias":[{"nota":121,"tipo":"DEROGACION_TOTAL","texto":"Artículo 377. Derogado por Decreto No. 262-2000 del 22 de diciembre del 2000 y publicado en el Diario Oficial La Gaceta Nº29,414 de fecha 26 de febrero del 2001. Ratificado por Decreto No. 38- 2001 del 16 de abril del 2001.publicado en el Diario Oficial Gaceta Nº29,489 de fecha 29 de mayo del 2001.","decretos":["262-2000","38-2001"]}],"correcciones_saneamiento":["ENCABEZADO_RETIRADO","LLAMADAS_DE_NOTA_RETIRADAS"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a377","derogado_por":"D.262-2000","clasificacion_propuesta":{"vigencia":"DEROGADO","rol":"CONTEXT","motivo":"DEROGADO por D.262-2000 según la edición CEDIJ; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','377','82ae0c99685fbe507ce253c745b8e6d7b7ae6bbbcd5f3eba6efccfda805740e7','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:378','mayalex_normativos','00_CONSTITUCIONAL','Queda derogada por esta Constitución, la emitida por la Asamblea Nacional Constituyente el tres de junio de mil novecientos sesenta y cinco.','378','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":380,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"5b2655b5ef18ee0562e60e346b4bc075519818ee7429a20093e20e7abb373174","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a378","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','378','5b2655b5ef18ee0562e60e346b4bc075519818ee7429a20093e20e7abb373174','OLA3_CON_2021_01',now()),
('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:379','mayalex_normativos','00_CONSTITUCIONAL','Esta Constitución será jurada en sesión pública y solemne y entrará en vigencia el veinte de enero de mil novecientos ochenta y dos.','379','Constitución de la República de Honduras (Decreto No. 131 de 1982)','{"norm_id":"HN:CONSTITUCION_REPUBLICA","instrumento_id":"CONSTITUCION_REPUBLICA","ingest_batch":"OLA3_CON_2021_01","ola":"OLA3","ordinal":381,"decreto":"131-1982","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición consolidada «Constitucion de la Republica (actualizada noviembre 2021).pdf» (Word 2019, 19-may-2023), con notas al pie de cada reforma, interpretación, adición y derogación.","pdf_sha256":"6d6e8e880a33dafd9b6dd8c4ac07291fb77af9ada0456e1b6cf0b0b17d882482","article_sha256":"9040b78d0e5584f02d9e8b978e44768cd05af525af2ac00ce2457302f4a67caf","ubicacion":["CAPITULO II","DE LA VIGENCIA DE LA CONSTITUCION"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":"mayalex_normativos:constitucion_1982_a379","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CONSTITUCION_REPUBLICA','379','9040b78d0e5584f02d9e8b978e44768cd05af525af2ac00ce2457302f4a67caf','OLA3_CON_2021_01',now())
ON CONFLICT (id) DO NOTHING;
DO $do$ DECLARE n int; BEGIN
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA3_CON_2021_01' AND metadata->>'norm_id' = 'HN:CONSTITUCION_REPUBLICA'
    AND instrumento_id = 'CONSTITUCION_REPUBLICA' AND jurisdiccion = 'HN' AND encode(sha256(convert_to(contenido, 'UTF8')), 'hex') = hash_contenido AND revision_pendiente = true AND es_norma_vigente IS NULL;
  IF n <> 381 THEN RAISE EXCEPTION 'post-insert prod (ocultas, hash correcto): % filas (esperadas 381)', n; END IF;
END $do$;
COMMIT;
